import assert from 'node:assert/strict'
import {readFileSync} from 'node:fs'
const form=readFileSync('src/features/client3/WatchOrderForm.tsx','utf8')
const app=readFileSync('src/WatchClient3App.tsx','utf8')
const source=readFileSync('shared/client3/watch-domain.ts','utf8')
assert(form.includes("import {SmartPickerInput} from '../../components/inputs/SmartPickerInput'"),'Use the actual Main SmartPicker component')
assert(form.includes('Название товара *')&&form.includes('Начните вводить название часов'),'Name is a direct free-text input')
assert(form.includes('options={suggestions.models}'),'Catalog must be suggestion-only, not required')
assert(form.includes('modelName:line.manual.modelName.trim()'),'Always submit a free model name')
assert(form.includes('watchVariantId:0'),'Never require catalog SKU on order creation')
assert(form.includes('canonical(WATCH_OPTIONS.movements,line.manual.movement)'),'Human labels must be translated to canonical values')
assert(form.includes('canonical(WATCH_OPTIONS.braceletMaterials,line.manual.braceletMaterial)'),'Leather has to retain its real watch code')
assert(form.includes('canonical(WATCH_OPTIONS.dialColors,line.manual.dialColor)'),'Dial color must be localized for UI')
assert(!form.includes('Выберите часы из каталога'),'Old mandatory catalog dropdown must be gone')
assert(!form.includes('Не нашли товар? Ввести вручную'),'No second manual-entry mode')
assert(!form.includes('Classic Watch'),'No artificial English name')
assert(!form.includes('manual:null'),'Free entry must be initial state')
assert(form.includes('refs')||form.includes('references'),'Use existing shared reference suggestions')
assert(app.includes('references={watchRefOptions}'),'Shared dictionaries shown in order form')
assert(!app.includes('catalogBusy?<article'),'Catalog loading must not block free order registration')
for (const label of ['Кварцевые','Механические','Стальной','Кожа','Каучук','Чёрный'])
 assert(source.includes(label),'User-facing basic options must be localized: '+label)
console.log('CLIENT3_FREE_ENTRY_MAIN_SMART_PICKER_UX_PASS')
